WITH kept_keys AS (SELECT promo_code, id FROM promotions INTERSECT SELECT promo_code, id FROM promotions WHERE promo_code <> 'BUNDLE'), reconciled AS (SELECT s.* FROM promotions s JOIN kept_keys k ON s.promo_code = k.promo_code AND s.id = k.id) SELECT promo_code, DATE_TRUNC('YEAR', ends_on) AS year_start, COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END) AS bundle_count, SIZE(COLLECT_SET(channel)) AS num_channels FROM reconciled GROUP BY ROLLUP (promo_code, DATE_TRUNC('YEAR', ends_on)) HAVING SIZE(COLLECT_SET(channel)) > 1 ORDER BY num_channels DESC;
